const fireLampSheet=new Image();fireLampSheet.assetSrc='assets/fire-lamp-v1.png';
function fireLampAlly(e){return e.hp>0&&Number.isFinite(e.max)&&e.max>0&&e.hp<e.max&&!e.boss&&!e.secret&&!e.ex&&!e.dummy&&e.species!=='r7e6';}
function beginFireLamp(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'fireRestoringLamp',bespoke:true,windup:1.5,origin:{x:e.x,y:e.y},targets:enemies.filter(target=>fireLampAlly(target)&&dist(e,target)<=300&&lineClear(e,target)).sort((a,b)=>a.hp/a.max-b.hp/b.max).slice(0,3),damage:0,threshold:Math.max(1,(e.max||e.hp)*.08),fired:false};}
const fireLampHitBase=hit;hit=(e,d)=>{let a=e.attack,hp=e.hp,direct=!e.dotTick;let result=fireLampHitBase(e,d);if(e.species==='r7e6'&&direct&&e.hp>0&&a?.pattern==='fireRestoringLamp'&&!a.fired&&e.attack===a){a.damage+=Math.max(0,hp-e.hp);if(a.damage+1e-8>=a.threshold){e.attack=null;e.state='idle';e.fireLampDark=2;e.t=1.5;playSound('impact',e.x,e.y);}}return result;};
const fireLampAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e6')return fireLampAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);if(e.fireLampDark>0){e.fireLampDark=Math.max(0,Math.round((e.fireLampDark-dt)*1e6)/1e6);e.state='idle';e.attack=null;return;}let a=e.attack;
 if(a?.pattern!=='fireRestoringLamp'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=300&&clear){beginFireLamp(e);return;}e.state='idle';if(d>800&&!e.aware||d<=180&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,66*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,16)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=1.5){a.fired=true;e.struck=true;for(let target of a.targets){if(!fireLampAlly(target)||!enemies.includes(target)||dist(e,target)>300||!lineClear(e,target))continue;let heal=Math.min(target.max-target.hp,target.max*.2);target.hp+=heal;texts.push({x:target.x,y:target.y-30,s:'+'+Math.round(heal),c:'#8edeb1',life:.7});}if(dist(p,a.origin)<=190+1e-8&&lineClear(a.origin,p))hurt(54);playSound('fire',e.x,e.y);}if(e.elapsed>=2.5){e.attack=null;e.state='idle';e.t=4;}
};
const fireLampDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e6'||!fireLampSheet.complete||!fireLampSheet.naturalWidth||!fireLampSheet.naturalHeight)return fireLampDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0||e.fireLampDark>0)f={row:2,col:3};else if(e.attack?.pattern==='fireRestoringLamp')f={row:2,col:e.elapsed<.6?0:e.elapsed<1.5?1:e.elapsed<1.8?2:3};let q=project(e.x,e.y),sw=fireLampSheet.naturalWidth/4,sh=fireLampSheet.naturalHeight/3,w=215,h=w*sh/sw,anchor=[.9,.87,.9][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,fireLampSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(fireLampSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const fireLampSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e6'?135:fireLampSizeBase(e);
const fireLampGroundBase=drawGroundEffects;drawGroundEffects=()=>{fireLampGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e6'):enemies)){if(e.species!=='r7e6'||e.hp<=0||!visibleAt(e.x,e.y))continue;if(e.fireLampDark>0){groundRing(e.x,e.y,30,'#9bddcf',2);continue;}let a=e.attack;if(a?.pattern!=='fireRestoringLamp')continue;if(e.elapsed<1.8)groundRing(e.x,e.y,190,a.fired?'#ffd397':'#e2a777',a.fired?3:1);if(!a.fired){groundRing(e.x,e.y,36,'#8edeb1',3);for(let target of a.targets){if(!fireLampAlly(target)||!enemies.includes(target)||dist(e,target)>300||!lineClear(e,target))continue;let q=project(e.x,e.y),r=project(target.x,target.y);groundRing(target.x,target.y,25,'#8edeb1',2);ctx.save();ctx.strokeStyle='#8edeb177';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(r.x,r.y);ctx.stroke();ctx.restore();}}}};
